def data():
    return json.loads(gzip.decompress(base64.b85decode(ARCHIVE.encode())).decode())

def git_path():
    cp = subprocess.run(['git','rev-parse','--path-format=absolute','--git-path','youtv-upgrade-backups'],
        cwd=ROOT,capture_output=True,text=True)
    if cp.returncode: raise RuntimeError('This must run inside the YouTV Git repository')
    p=Path(cp.stdout.strip()); return p if p.is_absolute() else ROOT/p

def merge3(local: str, base: str, incoming: str, name: str):
    with tempfile.TemporaryDirectory(prefix='youtv-v033-') as d:
        filenames=[]
        for label,content in [('local',local),('base',base),('incoming',incoming)]:
            path=Path(d)/label;path.write_text(content,encoding='utf-8');filenames.append(str(path))
        cp=subprocess.run(['git','merge-file','-p','-L','LOCAL:'+name,'-L','BASE:v0.32',
            '-L','TARGET:v0.33',*filenames],cwd=ROOT,capture_output=True)
        if cp.returncode != 0: raise ValueError('Three-way merge conflict; local file preserved: '+name)
        return cp.stdout.decode('utf-8')

def known_legacy_hls(s: str) -> bool:
    # v0.29-v0.32 builds have these exactly three public functions. Replacing
    # this particular legacy rewriter is intentional: the old regex cannot
    # safely implement DEFINE, steering or LL-HLS. Backups retain its full text.
    return (s.count('export function rewriteHls(')==1 and
        s.count('export function isHls(')==1 and
        s.count('export async function readTextStream(')==1 and
        'const bareTag' in s and 'return manifest.split(' in s and
        'parseHlsVariables' not in s and len(s)<9500)

def merge_one(name, old, expected, target):
    if old==target: return old, 'already current'
    if name in ('apps/worker/dashboard-worker.mjs','apps/web/public/dashboard-worker.mjs'):
        return target, 'regenerate matched release bundle'
    if name=='scripts/build-dashboard.cjs':
        if old is None or 'require(\'typescript\')' in old or 'require("typescript")' in old or "spawnSync('bun'" in old:
            return target, 'Bun-based shared dashboard builder'
        raise ValueError('Unknown customized bundle builder; refusing overwrite: '+name)
    if name=='apps/web/package.json':
        if old is None: raise ValueError('Missing apps/web/package.json')
        value=json.loads(old)
        build=value.get('scripts',{}).get('build','')
        command='node ../../scripts/build-dashboard.cjs'
        if command in build: return old, 'builder already integrated'
        if 'vite build' not in build: raise ValueError('Unsupported apps/web build script; not modifying')
        value['scripts']['build']=command+' && '+build
        return json.dumps(value,ensure_ascii=False,indent=2)+'\n', 'integrate generated Worker into web build'
    if old is None:
        if expected is not None: raise ValueError('Required source file is missing: '+name)
        return target, 'create new file'
    if expected is None:
        raise ValueError('An unexpected file already exists at '+name+'; refusing overwrite')
    if old==expected: return target, 'apply clean v0.32 change'
    if name=='apps/worker/src/hls.ts' and known_legacy_hls(old):
        return target, 'upgrade known legacy regex HLS rewriter (backed up)'
    # A prior interrupted patch can leave only the release number stale. Treat
    # that particular difference as bookkeeping, not a source-code conflict.
    if name in ('apps/worker/src/index.ts', 'apps/web/src/features/proxy/CloudflareGuide.tsx'):
        identifier = 'VERSION' if name.endswith('/index.ts') else 'WORKER_RELEASE'
        pattern = r'(const ' + identifier + r'\s*=\s*[\"\'])(\d+\.\d+\.\d+)([\"\'])'
        base_match = re.search(pattern, expected)
        local_match = re.search(pattern, old)
        if base_match and local_match:
            old = old[:local_match.start(2)] + base_match.group(2) + old[local_match.end(2):]
    if old==expected: return target, 'normalize prior release version and upgrade'
    return merge3(old,expected,target,name), 'merge local modifications with v0.33'

def run(apply: bool):
    if not (ROOT/'apps/worker/src/index.ts').exists(): raise RuntimeError('No YouTV source root found')
    bundle=data()
    pending=[]; observations=[]
    for name,item in bundle.items():
        p=ROOT/name
        if p.is_symlink(): raise ValueError('Refusing to modify symlink '+name)
        old=p.read_text(encoding='utf-8') if p.exists() else None
        merged, reason=merge_one(name,old,item['base'],item['target'])
        if merged!=old:
            pending.append((name,old,merged))
            observations.append((name,reason))
    # Validate all inter-file invariants before writing a single byte.
    pending_map={name:new for name,_,new in pending}
    def final(name):
        return pending_map.get(name,(ROOT/name).read_text(encoding='utf-8'))
    runtime=final('apps/worker/src/index.ts')
    guide=final('apps/web/src/features/proxy/CloudflareGuide.tsx')
    hls=final('apps/worker/src/hls.ts')
    if not re.search(r'const VERSION\s*=\s*[\'"]0\.33\.0[\'"]',runtime):
        raise ValueError('Worker runtime version is not 0.33.0; stopped before writing')
    if not re.search(r'const WORKER_RELEASE\s*=\s*[\'"]0\.33\.0[\'"]',guide):
        raise ValueError('Worker download code version is not 0.33.0')
    if 'parseHlsVariables' not in hls or 'rewriteSteeringJson' not in hls:
        raise ValueError('New HLS rewriter is incomplete')
    if final('apps/worker/dashboard-worker.mjs')!=final('apps/web/public/dashboard-worker.mjs'):
        raise ValueError('Copy/download bundle differs from Worker runtime bundle')
    if not final('apps/web/public/dashboard-worker.mjs').startswith('// YouTV Worker bundle version: v0.33.0\n'):
        raise ValueError('Unexpected Worker bundle version')
    if not pending:
        print('YouTV v0.33.0: already up to date; no source edits needed.')
        return
    print('Planned changes ('+str(len(pending))+' files):')
    for name,reason in observations: print(' - '+name+'  ['+reason+']')
    if not apply:
        print('DRY RUN successful. No file was modified. Run with --apply to install.')
        return
    root=git_path()
    stamp=dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    backup=root/('v033-'+stamp+'-'+str(os.getpid()))
    backup.mkdir(parents=True,exist_ok=False)
    (backup/'manifest.json').write_text(json.dumps([{'path':name,'existed':old is not None} for name,old,_ in pending],indent=2)+'\n')
    for name,old,_ in pending:
        if old is not None:
            path=backup/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(old,encoding='utf-8')
    completed=[]
    try:
        for name,old,new in pending:
            path=ROOT/name;path.parent.mkdir(parents=True,exist_ok=True)
            temp=path.with_name(path.name+'.youtv-v033-tmp')
            temp.write_text(new,encoding='utf-8')
            os.replace(temp,path)
            completed.append((path,old))
    except Exception:
        for path,old in reversed(completed):
            if old is None:path.unlink(missing_ok=True)
            else:path.write_text(old,encoding='utf-8')
        raise
    print('Applied YouTV v0.33.0; previous versions saved to '+str(backup))
    print('Run: bun run check && bun run test && bun run build')
    print('Run: cmp apps/worker/dashboard-worker.mjs apps/web/public/dashboard-worker.mjs')
    print('Stage only intended changes; your Playlist.m3u was not modified.')

if __name__=='__main__':
    parser=argparse.ArgumentParser(description='Safe, conflict-aware YouTV HLS upgrade')
    mode=parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--check',action='store_true',help='validate and show changes only')
    mode.add_argument('--apply',action='store_true',help='validate then apply, with backups')
    args=parser.parse_args()
    try:run(args.apply)
    except Exception as e:
        print('UPGRADE ABORTED (no changes were applied unless stated): '+str(e),file=sys.stderr)
        sys.exit(1)
